{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum(allocations)
    if remaining < 0:
        remaining = 0
    indices = list(range(n))
    indices.sort(key=lambda i: (-segments[i]['importance'], i))
    while remaining > 0:
        allocated = False
        for i in indices:
            seg = segments[i]
            max_extra = seg['capacity'] - allocations[i]
            if max_extra <= 0:
                continue
            take = min(remaining, max_extra)
            allocations[i] += take
            remaining -= take
            allocated = True
            if remaining == 0:
                break
        if not allocated:
            break
    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': total}"
}
